//   Course Clips/8-16BackGFX / layer 'Layer 2' / frame 3
void frame_5756_1(Activation& scope) {
    _root["Course"]["FrontGFX"]["defeated"] = false;
    stop();
    scope["rot"] = 0;
    scope["endcount"] = 0;
    scope["onEnterFrame"] = scope.function([](Activation& scope) -> Value {
        scope["rot"] += 0.004;
        scope["bomb1"]["_x"] = Math["cos"](scope["rot"]) * 450;
        scope["bomb1"]["_y"] = Math["sin"](scope["rot"]) * 450;
        scope["bomb2"]["_x"] = Math["cos"](scope["rot"] + 2 * Math["PI"] * (0.2)) * 450;
        scope["bomb2"]["_y"] = Math["sin"](scope["rot"] + 2 * Math["PI"] * (0.2)) * 450;
        scope["bomb3"]["_x"] = Math["cos"](scope["rot"] + 2 * Math["PI"] * (0.4)) * 450;
        scope["bomb3"]["_y"] = Math["sin"](scope["rot"] + 2 * Math["PI"] * (0.4)) * 450;
        scope["bomb4"]["_x"] = Math["cos"](scope["rot"] + 2 * Math["PI"] * (0.6)) * 450;
        scope["bomb4"]["_y"] = Math["sin"](scope["rot"] + 2 * Math["PI"] * (0.6)) * 450;
        scope["bomb5"]["_x"] = Math["cos"](scope["rot"] + 2 * Math["PI"] * (0.8)) * 450;
        scope["bomb5"]["_y"] = Math["sin"](scope["rot"] + 2 * Math["PI"] * (0.8)) * 450;
        scope["bombgfx1"]["_x"] = scope["bomb1"]["_x"];
        scope["bombgfx1"]["_y"] = scope["bomb1"]["_y"] + 50;
        scope["bombgfx2"]["_x"] = scope["bomb2"]["_x"];
        scope["bombgfx2"]["_y"] = scope["bomb2"]["_y"] + 50;
        scope["bombgfx3"]["_x"] = scope["bomb3"]["_x"];
        scope["bombgfx3"]["_y"] = scope["bomb3"]["_y"] + 50;
        scope["bombgfx4"]["_x"] = scope["bomb4"]["_x"];
        scope["bombgfx4"]["_y"] = scope["bomb4"]["_y"] + 50;
        scope["bombgfx5"]["_x"] = scope["bomb5"]["_x"];
        scope["bombgfx5"]["_y"] = scope["bomb5"]["_y"] + 50;
        ///
        scope["camCenter"]["_x"] = (_root["Course"]["FrontGFX"]["Bowser"]["_x"] + ((_root["Course"]["Char"]["_x"] - scope["_x"]) * 2)) / 3;
        scope["camCenter"]["_y"] = (_root["Course"]["FrontGFX"]["Bowser"]["_y"] + ((_root["Course"]["Char"]["_y"] - scope["_y"]) * 2)) / 3;
        scope["distance"] = Math["sqrt"](Math["pow"]((_root["Course"]["FrontGFX"]["Bowser"]["_x"] - (_root["Course"]["Char"]["_x"] - scope["_x"])), 2) + Math["pow"]((_root["Course"]["FrontGFX"]["Bowser"]["_y"] - (_root["Course"]["Char"]["_y"] - scope["_y"])), 2));
        if (_root["Course"]["FrontGFX"]["Bowser"]["HP"] <= 0) {
            //play();
            //onEnterFrame = null;
            if (scope["endcount"] == 0) {
                // transtion
            }
            if (scope["endcount"] > 11) {
                _root["gotoAndStop"]("Ending");
                _root["RemoveCourse"]();
            }
            scope["endcount"]++;
        }
        return undefined;
    });
}

