void frame_5351_0(Activation& scope) {
    stop();
    scope["count"] = 0;
    scope["onEnterFrame"] = scope.function([](Activation& scope) -> Value {
        if (scope["count"] > 3 && _root["Course"]["Char"]["air"] == false) {
            if (scope.self["box"]["hitTest"](_root["Course"]["Char"]["charClip"]["body"]) || scope.self["box"]["hitTest"]((_root["Course"]["Char"]["_x"] * _root["coursescale"] / 100) + _root["Course"]["_x"], ((_root["Course"]["Char"]["_y"] - 15) * _root["coursescale"] / 100) + _root["Course"]["_y"], true)) {
                if (strictNotEquals(_root[scope["key"]], true)) {
                    //
                    _root["Course"]["Char"]["attack"] = true;
                    _root["Course"]["Char"]["attackFrame"] = "Item";
                    _root["heldItemObtained"] = scope["key"];
                    scope["keycount"] = 0;
                    if (_root["lvl8keyA"] == true) {
                        scope["keycount"]++;
                    }
                    if (_root["lvl8keyB"] == true) {
                        scope["keycount"]++;
                    }
                    if (_root["lvl8keyC"] == true) {
                        scope["keycount"]++;
                    }
                    if (_root["lvl8keyD"] == true) {
                        scope["keycount"]++;
                    }
                    if (scope["keycount"] == 0) {
                        _root["heldItemMessage"] = "You have 1 of Bowser's Keys!  There should be 3 more inside the Main Hall!";
                    }
                    if (scope["keycount"] == 1) {
                        _root["heldItemMessage"] = "You have 2 Bowser Keys!  The Cannon is now unlocked!  Use it to reach the upper story!";
                    }
                    if (scope["keycount"] == 2) {
                        _root["heldItemMessage"] = "You have 3 Bowser Keys!  One more!";
                    }
                    if (scope["keycount"] == 3) {
                        _root["heldItemMessage"] = "You have all 4 Bowser Keys!";
                    }
                }
                _root[scope["key"]] = true;
                //
                gotoAndStop(6);
            }
        } else {
            scope["count"]++;
        }
        return undefined;
    });
    gotoAndStop(scope["key"]);
}

